    results.append(('update',409,'ok',r))
except Exception as e:
    results.append(('update',409,'fail',str(e)))

# Disable all other alarms
for aid in [407,408,410,412,413,411]:
    try:
        r=apis.phone.update_alarm(alarm_id=aid, access_token=access_token, enabled=False)
        results.append(('disable',aid,'ok',r))
    except Exception as e:
